// ---- Morning Doxology: add Eng-Arabic ----
const morningDoxology = seasons
  .flatMap((s) => s.services)
  .flatMap((s) => s.hymns)
  .find((h) => h.id.endsWith('-morning-doxology'));

if (morningDoxology) {
  morningDoxology.versions = morningDoxology.versions.filter(
    (v) => v.language !== 'englishArabic'
  );

  morningDoxology.versions.push(
    {
      language: 'englishArabic',
      text: 'Nesgod lel-Ab wel-Ibn, wel-Roh el-Qodos, es-salamo lel-kanisa, beit el-malaika.\n\nEs-salamo lel-Azra, elli waladet mokhalisna, es-salamo le-Ghabrial, elli bashsharha.\n\nEs-salamo le-Mikhail, ra\'is el-malaika, es-salamo lel-arba\'a wel-\'eshrin, qessisan.\n\nEs-salamo lel-Sharubim, es-salamo lel-Sarafim, es-salamo le-gamee\' el-taghamat, es-samaya\'ia.\n\nEs-salamo le-Yohanna, es-sabeq el-\'azim, es-salamo lel-ithnay \'ashar, rasoolan.\n\nEs-salamo le-abina Morqos, el-Engili, mobaddid, el-awthan.\n\nEs-salamo le-Estefanos, el-shaheed el-awwal, es-salamo le-Gerges, kawkab el-sobh.\n\nEs-salamo le-gamee\' sofoof, el-shohada, es-salamo le-Anba Antonios, wel-thalatha el-Maqarat.\n\nEs-salamo le-gamee\' sofoof, lobbas el-saleeb, es-salamo le-gamee\' el-qiddiseen, elladhina ardaw el-Rab.\n\nAyyoha el-Maseeh malikna, be-salawatihim, esna\' ma\'ana rahma, fi malakootak.\n\n(For Our Lord Jesus Christ)\n\nAyyoha el-noor el-haqeeqi, elladhi yodee\', le-kolli ensan, atin ela el-\'alam.\n\nAtaita ela el-\'alam, be-mahabbatika lel-bashar, wa kol el-khaleeqa, tahallalat be-magi\'ik.\n\nKhallasta Adam, min el-ghawaya, wa \'ataqta Hawwa, min talaqat el-mawt.\n\nA\'taitana, roh el-bonowwa, nosabbehok wa nobarikok, ma\'a mala\'ikatik.\n\n\'Indama yadkhol, waqt bakir ilaina, ayyoha el-Maseeh elahna, el-noor el-haqeeqi.\n\nFalteshriq feena, hawas el-noor, wa la toghatteena, zolmat el-alam.\n\nLe-key nosabbehok, \'aqliyyan, ma\'a Dawood, sarikheen, nahwak qa\'ileen.\n\n"Sabaqa an balaghat, \'aynay waqt el-sahar, le-atlo, gamee\' aqwalik."\n\nEsma\' sawtana, ka-\'azeem rahmatik, wa naggina ayyoha el-Rab elahna, hasab ra\'afatik.\n\nYa Allah el-mohtam, sani\' el-khayrat, modabbir mokhtareeh, hasanan.\n\nEl-modabbir el-qawi, lel-moltagi\'een, el-motashawweq le-khalas, wa nagat kol ahad.\n\nBe-salahik hayya\'ta, lana el-layl, an\'im lana be-hadha el-yawm, wa nahno be-ghayr khateeya.\n\nLe-nastahiqq an narfa\', aydeena elaik, amamak be-ghayr ghadab, wa la fikr radi\'.\n\nFi hadha el-sahar, sahhil toroqana, el-dakhiliyya wel-kharigiyya, be-sitrik el-mofrih.\n\nLe-nantiq be-\'adlik, kol yawm, wa nomagged qowwatak, ma\'a Dawood el-nabi.\n\nQa\'ileen "Be-salamik, ayyoha el-Maseeh mokhalisna, raqadna wa qomna, li-annana tawakkalna \'alaik.\n\nHa ma howa el-hasan, wa ma howa el-helw, illa ettifaq ekhwa, sakineen ma\'an."\n\nMottafiqeen, be-mahabba haqeeqiyya, engeeliyya, ka-mithl el-rosol.\n\nMithl el-tayyeb, \'ala ra\'s el-Maseeh, el-nazil \'ala el-lihya, ela asfal el-rigleen.\n\nYamsah kol yawm, el-shoyookh, wel-sibyan wel-fatayat, wel-khoddam.\n\nHa\'olaa elladhina, allafahom el-Roh el-Qodos ma\'an, mithl qeethara mosabbiheen, Allah kol heen.\n\nBe-mazameer wa tasabeeh, wa taraneem roheyya, el-nahar wel-layl, be-qalb la yafter.\n\n(For the Virgin)\n\nAnti ya omm el-noor, el-mokarrama walidat el-Ilah, hamalti el-Kalima, ghayr el-mahwi.\n\nWa min ba\'d an waladtih, baqeeti \'azra, no\'azzemok be-tasabeeh, wa barakat.\n\nLi-annahu be-eradatih, wa masarrat abeeh, wel-Roh el-Qodos, ata wa khallasna.\n\nWa nahno ayadan, natlob an nafooz, be-rahma be-shafa\'atik, lada moheb el-bashar.\n\nEl-bokhoor el-mokhtar, elladhi le-betooliyyatik, sa\'ada ela, korsi el-Ab.\n\nAfdal min bokhoor, el-Sharubim, wel-Sarafim, ya Maryam el-\'Azra.\n\nEs-salamo lel-sama\' el-gadeeda, elleti sana\'aha el-Ab, wa ga\'alaha mawdi\' raha, le-ibnihi el-Habeeb.\n\nEs-salamo lel-korsi, el-molookeyy, elladhi lel-mahmool, \'ala el-Sharubim.\n\nEs-salamo le-shafee\'at, nofoosina, anti bel-haqeeqa, fakhr ginsina.\n\nIshfa\'i feena, ya momtali\'at ne\'ma, amama mokhalisna, Rabbona Yasoo\' el-Maseeh.\n\nLe-key yothabbitana, fil-eman el-mostaqeem, wa yon\'em lana, be-maghfirat khataya-na.\n\nBe-shafa\'at, walidat el-Ilah el-qiddeesa Maryam, ya Rab en\'im lana, be-maghfirat khataya-na.\n\n(For the Angels)\n\nAloof aloof, wa rabawat rabawat, ro\'asa\' mala\'ika, wa mala\'ika moqaddaseen.\n\nWoqoof amama, korsi, dabet el-kol, sarikheen qa\'ileen:\n\n"Qoddoos qoddoos, qoddoos bel-haqeeqa, el-magd wel-karama, yaleeqan bel-thaloot."\n\nBe-shafa\'at, gamee\' sofoof el-mala\'ika, ya Rab en\'im lana, be-maghfirat khataya-na.\n\n(For the Apostles)\n\nAba\'ona el-rosol, bashsharoo fil-omam, be-engeel, Yasoo\' el-Maseeh.\n\nKharagat aswatohom, ela el-ard kolliha, wa balagha kalamohom, ela aqtar el-maskoona.\n\nBe-salawat, sadati el-aba\' el-rosol, ya Rab en\'im lana, be-maghfirat khataya-na.\n\n(For the Martyrs)\n\nAkaleel ghayr modmahilla, ga\'alaha el-Rab, \'ala gamee\', sofoof el-shohada.\n\nAnqadhahom wa khallasahom, li-annahom eltaga\'oo elaih, wa \'ayyadoo ma\'ah, fi malakootih.\n\nBe-salawat, gamee\' sofoof el-shohada, ya Rab en\'im lana, be-maghfirat khataya-na.\n\n(For the Saints)\n\nQiddeesook, yobarikoonak, wa yantiqoon be-magd, malakootak.\n\nMalakootak ya elahi, malakoot abadi, wa robooboyyatak, ela kol el-agyal.\n\nBe-salawat, kaffat masaff labisi el-saleeb, wel-abrar wel-siddeeqeen, ya Rab en\'im lana, be-maghfirat khataya-na.\n\n(For the Patriarchs and the Prophets)\n\nEs-salamo le-Eliyya, el-nabi el-mota\'affif, wa Elisha\', talmeezuhu el-mokhtar.\n\nEl-mobashshir el-\'azeem, fi koorat Misr, Morqos el-rasool, modabbiroha el-awwal.\n\nAnti hiya omm Allah, ya Maryam el-\'Azra, otlobi minhu \'anna, an yarham ginsana.\n\nEl-batreyark el-\'azeem, abouna Anba Sawiros, elladhi anarat ta\'aleemuhu, el-moqaddasa \'oqoolana.\n\nAbouna el-mo\'tarif, Anba Dioscoros, haraba \'an el-eman, didd el-haratiqa.\n\nWa kol aba\'ina, elladhina ardaw el-Rab, barakatohom el-moqaddasa, takoon lana harisan.\n\nBe-salawatihim, en\'im lana ya Allah, be-maghfirat khataya-na, wa a\'tina salaman.',
    }
  );
}

// ---- Annual > Morning Praises: only 2 hymns ----
const annualMorningPraises = seasons
  .find((s) => s.id === 'annual')
  ?.services.find((s) => s.id === 'annual-morning-praises');

if (annualMorningPraises) {
  annualMorningPraises.hymns = annualMorningPraises.hymns.filter(
    (h) => h.id.endsWith('-morning-doxology')
  );

  annualMorningPraises.hymns.push({
    id: 'annual-morning-praises-adam-theotokias-conclusion',
    title: 'Ⲛⲉⲕⲛⲁⲓ ⲱ̀ Ⲡⲁⲛⲟⲩϯ (Conclusion of the Adam Theotokias)',
    versions: [
      {
        language: 'coptic',
        text: 'Ⲛⲉⲕⲛⲁⲓ ⲱ̀ Ⲡⲁⲛⲟⲩϯ: ϩⲁⲛⲁⲧϭⲓⲏ̀ⲡⲓ ⲙ̀ⲙⲱⲟⲩ: ⲥⲉⲟϣ ⲉ̀ⲙⲁϣⲱ: ⲛ̀ϫⲉ ⲛⲉⲕⲙⲉⲧϣⲉⲛϩⲏⲧ.\n\nⲚⲓⲧⲉⲗⲧⲓⲗⲓ ⲙ̀ⲙⲟⲩⲛϩⲱⲟⲩ: ⲥⲉⲏⲡ ⲛ̀ⲧⲟⲧⲕ ⲧⲏⲣⲟⲩ: ⲡⲓⲕⲉϣⲱ ⲛ̀ⲧⲉ ⲫ̀ⲓⲟⲙ: ⲥⲉⲭⲏ ⲛⲁϩⲣⲉⲛ ⲛⲉⲕⲃⲁⲗ.\n\nⲒⲉ ⲁⲩⲏⲣ ⲙⲁⲗⲗⲟⲛ: ⲛⲓⲛⲟⲃⲓ ⲛ̀ⲧⲉ ⲧⲁⲯⲩⲭⲏ: ⲛⲁⲓ ⲉⲑⲟⲩⲱⲛϩ ⲉ̀ⲃⲟⲗ: ⲙ̀ⲡⲉⲕⲙ̀ⲑⲟ Ⲡⲁϭⲟⲓⲥ.\n\nⲚⲓⲛⲟⲃⲓ ⲉ̀ⲧⲁⲓⲁⲧⲟⲩ: Ⲡⲁϭⲟⲓⲥ ⲛ̀ⲛⲉⲕⲉⲣⲡⲟⲩⲙⲉⲩⲓ̀: ⲟⲩⲇⲉ ⲙ̀ⲡⲉⲣϯϩ̀ⲑⲏⲕ: ⲉ̀ⲛⲁⲁ̀ⲛⲟⲙⲓⲁ.\n\nϪⲉ ⲡⲓⲧⲉⲗⲱⲛⲏⲥ ⲁⲕⲥⲟⲧⲡϥ: ϯⲡⲟⲣⲛⲏ ⲁⲕⲥⲱϯ ⲙ̀ⲙⲟⲥ: ⲡⲓⲥⲟⲛⲓ ⲉⲧⲥⲁⲟⲩⲓ̀ⲛⲁⲙ: Ⲡⲁϭⲟⲓⲥ ⲁⲕⲉⲣⲡⲉϥⲙⲉⲩⲓ̀.\n\nⲀ̀ⲛⲟⲕ ϩⲱ Ⲡⲁϭⲟⲓⲥ: ϧⲁ ⲡⲓⲣⲉϥⲉⲣⲛⲟⲃⲓ: ⲙⲁⲧ̀ⲥⲁⲃⲟⲓ ⲛ̀ⲧⲁⲓ̀ⲣⲓ: ⲛ̀ⲟⲩⲙⲉⲧⲁⲛⲟⲓⲁ.\n\nϪⲉ ⲭ̀ⲟⲩⲱϣ ⲙ̀ⲫ̀ⲙⲟⲩ ⲁⲛ: ⲙ̀ⲡⲓⲣⲉϥⲉⲣⲛⲟⲃⲓ: ⲙ̀ⲫ̀ⲣⲏϯ ⲛ̀ⲧⲉϥⲧⲁⲥⲑⲟϥ: ⲛ̀ⲧⲉⲥⲱⲛϧ ⲛ̀ϫⲉ ⲧⲉϥⲯⲩⲭⲏ.\n\nⲘⲁⲧⲁⲥⲑⲟⲛ Ⲫ̀ⲛⲟⲩϯ: ⲉ̀ϧⲟⲩⲛ ⲉ̀ⲡⲉⲕⲟⲩϫⲁⲓ: ⲁ̀ⲣⲓⲟⲩⲓ̀ ⲛⲉⲙⲁⲛ: ⲕⲁⲧⲁ ⲧⲉⲕⲙⲉⲧⲁ̀ⲅⲁⲑⲟⲥ.\n\nϪⲉ ⲛ̀ⲑⲟⲕ ⲟⲩⲁ̀ⲅⲁⲑⲟⲥ: ⲟⲩⲟϩ ⲛ̀ⲛⲁⲏⲧ: ⲙⲁⲣⲟⲩⲧⲁϩⲟⲛ ⲛ̀ⲭⲱⲗⲉⲙ: ⲛ̀ϫⲉ ⲛⲉⲕⲙⲉⲧϣⲉⲛϩⲏⲧ.\n\nϢⲉⲛϩⲏⲧ ϧⲁⲣⲟⲛ ⲧⲏⲣⲉⲛ: Ⲡ̀ϭⲟⲓⲥ Ⲫ̀ⲛⲟⲩϯ Ⲡⲉⲛⲥⲱⲧⲏⲣ: ⲟⲩⲟϩ ⲛⲁⲓ ⲛⲁⲛ: ⲕⲁⲧⲁ ⲡⲉⲕⲛⲓϣϯ ⲛ̀ⲛⲁⲓ.\n\nⲚⲁⲓ ⲕ̀ⲓ̀ⲣⲓ ⲙ̀ⲡⲟⲩⲙⲉⲩⲓ̀: ⲱ̀ Ⲡⲉⲛⲛⲏⲃ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ: ⲉⲕⲉ̀ϣⲱⲡⲓ ϧⲉⲛ ⲧⲉⲛⲙⲏϯ: ⲉⲕⲱϣ ⲉ̀ⲃⲟⲗ ⲉⲕϫⲱ ⲙ̀ⲙⲟⲥ.\n\nϪⲉ ⲧⲁϩⲓⲣⲏⲛⲏ ⲁ̀ⲛⲟⲕ: ϯϯ ⲙ̀ⲙⲟⲥ ⲛⲱⲧⲉⲛ: ⲧ̀ϩⲓⲣⲏⲛⲏ ⲙ̀Ⲡⲁⲓⲱⲧ: ϯⲭⲱ ⲙ̀ⲙⲟⲥ ⲛⲉⲙⲱⲧⲉⲛ.\n\nⲠ̀ⲟⲩⲣⲟ ⲛ̀ⲧⲉ ϯϩⲓⲣⲏⲛⲏ: ⲙⲟⲓ ⲛⲁⲛ ⲛ̀ⲧⲉⲕϩⲓⲣⲏⲛⲏ: ⲥⲉⲙⲛⲓ ⲛⲁⲛ ⲛ̀ⲧⲉⲕϩⲓⲣⲏⲛⲏ: ⲭⲁ ⲛⲉⲛⲛⲟⲃⲓ ⲛⲁⲛ ⲉ̀ⲃⲟⲗ.\n\nϪⲱⲣ ⲉ̀ⲃⲟⲗ ⲛ̀ⲛⲓϫⲁϫⲓ: ⲛ̀ⲧⲉ Ϯⲉⲕⲕⲗⲏⲥⲓⲁ: ⲁ̀ⲣⲓⲥⲟⲃⲧ ⲉ̀ⲣⲟⲥ: ⲛ̀ⲛⲉⲥⲕⲓⲙ ϣⲁ ⲉ̀ⲛⲉϩ.\n\nⲈⲙⲙⲁⲛⲟⲩⲏⲗ Ⲡⲉⲛⲛⲟⲩϯ: ϧⲉⲛ ⲧⲉⲛⲙⲏϯ ϯⲛⲟⲩ: ϧⲉⲛ ⲡ̀ⲱ̀ⲟⲩ ⲛ̀ⲧⲉ Ⲡⲉϥⲓⲱⲧ: ⲛⲉⲙ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ.\n\nⲚ̀ⲧⲉϥⲥ̀ⲙⲟⲩ ⲉ̀ⲣⲟⲛ ⲧⲏⲣⲉⲛ: ⲛ̀ⲧⲉϥⲧⲟⲩⲃⲟ ⲛ̀ⲛⲉⲛϩⲏⲧ: ⲛ̀ⲧⲉϥⲧⲁⲗϭⲟ ⲛ̀ⲛⲓϣⲱⲛⲓ: ⲛ̀ⲧⲉ ⲛⲉⲛⲯⲩⲭⲏ ⲛⲉⲙ ⲛⲉⲛⲥⲱⲙⲁ.\n\nⲦⲉⲛⲟⲩⲱϣⲧ ⲙ̀ⲙⲟⲕ ⲱ̀ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ: ⲛⲉⲙ Ⲡⲉⲕⲓⲱⲧ ⲛ̀ⲁ̀ⲅⲁⲑⲟⲥ: ⲛⲉⲙ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ: ϫⲉ (ⲁⲕⲧⲱⲛⲕ/ ⲁⲕⲓ̀) ⲁⲕⲥⲱϯ ⲙ̀ⲙⲟⲛ.',
      },
      {
        language: 'englishCoptic',
        text: 'Neknai ō Panouti: hanattshi-ēpi emmōou: seosh emashō: enje nekmetshenhēt.\n\nNiteltili emmounhōou: seēp entotk tērou: pikeshō ente efiom: sekhē nahren nekval.\n\nIe auēr mallon: ninovi ente tapsukhē: nai ethouōnh evol: empekemtho Patshois.\n\nNinovi etaiatou: Patshois ennekerpoumeu-i: oude emperti-ehthēk: ena-anomia.\n\nJe pitelōnēs aksotpf: tipornē aksōti emmos: pisoni etsaou-inam: Patshois akerpefmeu-i.\n\nAnok hō Patshois: kha pirefernovi: ma-etsavoi enta-iri: enoumetanoia.\n\nJe ekhouōsh emefmou an: empirefernovi: emefrēti enteftasthof: entesōnkh enje tefpsukhē.\n\nMatasthon Efnouti: ekhoun epekoujai: ariou-i neman: kata tekmetagathos.\n\nJe enthok ou-agathos: ouoh ennaēt: maroutahon enkhōlem: enje nekmetshenhēt.\n\nShenhēt kharon tēren: Eptshois Efnouti Pensōtēr: ouoh nai nan: kata peknishti ennai.\n\nNai ekiri empoumeu-i: ō Pennēb Pi-ekhristos: ekeshōpi khen tenmēti: ekōsh evol ekjō emmos.\n\nJe tahirēnē anok: titi emmos nōten: ethirēnē em-Paiōt: tikhō emmos nemōten.\n\nEpouro ente tihirēnē: moi nan entekhirēnē: semni nan entekhirēnē: kha nennovi nan evol.\n\nJōr evol ennijaji: ente Tiekklēsia: arisobt eros: enneskim sha eneh.\n\nEmmanouēl Pennouti: khen tenmēti tinou: khen epōou ente Pefiōt: nem Pi-epneuma ethouab.\n\nEntefesmou eron tēren: enteftouvo ennenhēt: enteftaltsho ennishōni: ente nenpsukhē nem nensōma.\n\nTenouōsht emmok ō Pi-ekhristos: nem Pekiōt enagathos: nem Pi-epneuma ethouab: je (aktōnk/ aki) aksōti emmon.',
      },
      {
        language: 'english',
        text: 'Your mercies O my God, are countless, and exceedingly plenteous, are Your compassion.\n\nAll the rain drops, are counted by You, and the sand of the sea, is before Your eyes.\n\nHow much more are, the sins of my soul, manifest before You, O my Lord.\n\nThe sins that I have committed, do not remember my Lord, and do not count, my iniquities.\n\nFor You have chosen the publican, and the adulteress You have saved, and the right-hand thief, my Lord You have remembered.\n\nAnd me too, the sinner, teach me O my Master, to offer repentance.\n\nFor You do not desire, the death of a sinner, but rather that he returns, and that his soul may live.\n\nRestore us O God, to Your salvation, and deal with us, according to Your goodness.\n\nFor You are good, and merciful, let Your compassion, speedily come to us.\n\nHave compassion upon us all, O Lord God our Savior, and have mercy upon us, according to Your great mercy.\n\nRemember those, O Christ our Master, be among us, and proclaim and say.\n\n"My peace I, give to you, the peace of My Father, I leave with you."\n\nO King of peace, grant us Your peace, render unto us Your peace, and forgive us our sins.\n\nDisperse the enemies, of the Church, and fortify her that she, may not be shaken forever.\n\nEmmanuel our God, is now in our midst, with the glory of His Father, and the Holy Spirit.\n\nMay He bless us all, and purify our hearts, and heal the sicknesses, of our souls and bodies.\n\nWe worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.',
      },
      {
        language: 'englishArabic',
        text: 'Maraheemak ya elahi, ghayr mohsah, wa kathira giddan, hiya ra\'afatik.\n\nQatarat el-matar, mohsah \'indak gamee\'uha, wa raml el-bahr, ka\'in amama \'aynayk.\n\nFakam bel-harey, khataya nafsi, hadhihi el-zahira, amamak ya rabbi.\n\nEl-khataya elleti sana\'tuha, ya rabbi la tadhkoruha, wa la tahsib, athami.\n\nFa\'inna el-\'ashshar ikhtartah, wel-zaniya khallastaha, wel-liss el-yameen, ya sayyidi dhakartah.\n\nWa ana ayadan el-khati\', ya sayyidi, \'allimni, an asna\' tawba.\n\nLi\'annak la tasha\', mawt el-khati\', mithl an yarge\', wa tahya nafsoh.\n\nRadduna ya Allah, ela khalasik, wa \'amilna, ka-salahik.\n\nLi\'annak anta saleh, wa rahoom, fal-yodrikna, ra\'afatik sari\'an.\n\nTara\'af \'alaina kolena, ayyoha el-Rab el-Ilah, mokhalisna warhamna, ka-\'azeem rahmatik.\n\nHa\'ola\' adhkorhom, ya sayyidna el-Maseeh, kun fi wasatina, sarikhan qa\'ilan:\n\n"Salami ana, o\'teekom, salam abi, atrukuhu ma\'akom."\n\nYa malik el-salam, a\'tina salamak, qarrir lana salamak, wagh-fir lana khataya-na.\n\nFarriq a\'da\' el-kanisa, wa hassinha, fala tatazaz\'a, ela el-abad.\n\n\'Emmanoeil elahna, fi wasatina el-an, be-magd abeeh, wel-Roh el-Qodos.\n\nLi-yobarikna kolena, wa yotahhir qoloobana, wa yashfi amrad, nofoosina wa agsadina.\n\nNasgod lak ayyoha el-Maseeh, ma\'a abeek el-saleh, wel-Roh el-Qodos, li\'annak (qomt/ataita) wa khallastana.',
      },
      {
        language: 'arabic',
        text: 'مراحمك يا إلهي، غير محصاة، وكثيرة جداً، هي رأفاتك.\n\nقطرات المطر، محصاة عندك جميعها، ورمل البحر، كائن أمام عينيك.\n\nفكم بالحري، خطايا نفسي، هذه الظاهرة، أمامك يا ربي.\n\nالخطايا التي صنعتها، يا ربي لا تذكرها، ولا تحسب، آثامي.\n\nفإن العشار إخترته، والزانية خلصتها، واللص اليمين، يا سيدي ذكرته.\n\nوأنا أيضاً الخاطئ، يا سيدي، علمني، أن أصنع توبة.\n\nلأنك لا تشاء، موت الخاطئ، مثل أن يرجع، وتحيا نفسه.\n\nردنا يا الله، إلى خلاصك، وعاملنا، كصلاحك.\n\nلأنك أنت صالح، ورحوم، فلتدركنا، رأفاتك سريعاً.\n\nترأف علينا كلنا، أيها الرب الإله، مخلصنا وإرحمنا، كعظيم رحمتك.\n\nهؤلاء أذكرهم، يا سيدنا المسيح، كن في وسطنا، صارخاً قائلاً:\n\n"سلامي أنا، أعطيكم، سلام أبي، أتركه معكم."\n\nيا ملك السلام، أعطنا سلامك، قرر لنا سلامك، وإغفر لنا خطايانا.\n\nفرِّق أعداء الكنيسة، وحصنها، فلا تتزعزع، إلى الأبد.\n\nعمانوئيل إلهنا، في وسطنا الآن، بمجد أبيه، والروح القدس.\n\nليباركنا كلنا، ويطهر قلوبنا، ويشفي أمراض، نفوسنا وأجسادنا.\n\nنسجد لك أيها المسيح، مع أبيك الصالح، والروح القدس، لأنك (قمت/أتيت) وخلصتنا.',
      },
    ],
  });
}

